const { Client, Account, TablesDB, ID, Query, Permission, Role } = window.Appwrite;

const C = {
  endpoint: "https://nyc.cloud.appwrite.io/v1",
  projectId: "6b01e299000b19ac36ce",
  databaseId: "6b01e350001ca47807e5",
  tables: {
    profiles: "profiles",
    settings: "6b01e569002a228a1c5b",
    transactions: "6b01e6aa0036b4223488",
    goals: "6b01e8700035f839daea",
    accounts: "6b01fc9a00179915f55c",
    categories: "6b01fd500025ac427542",
    bills: "6b01fdb800341288b640",
    cards: "6b020079002ad9473ae5"
  }
};

const client = new Client().setEndpoint(C.endpoint).setProject(C.projectId);
const account = new Account(client);
const db = new TablesDB(client);
let user = null;
let state = { page:"home", sub:"overview", transactions:[], goals:[], accounts:[], categories:[], bills:[], cards:[], settings:null };

const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const n=v=>{if(typeof v==="number")return Number.isFinite(v)?v:0;const x=String(v??"").replace(/\s/g,"").replace(".",".").replace(",",".");const z=Number(x);return Number.isFinite(z)?z:0};
const money=v=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(n(v));
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[c]));
const cap=s=>String(s||"").trim().replace(/\s+/g," ").toLowerCase().replace(/(^|\s)\S/g,c=>c.toUpperCase());
const today=()=>new Date().toISOString().slice(0,10);
const monthKey=d=>String(d||"").slice(0,7);
const monthLabel=m=>new Intl.DateTimeFormat("pt-BR",{month:"long",year:"numeric"}).format(new Date(`${m}-01T12:00:00`));
const dateBR=v=>{if(!v)return"—";const d=new Date(`${String(v).slice(0,10)}T12:00:00`);return Number.isNaN(d.getTime())?String(v):d.toLocaleDateString("pt-BR")};
const toast=(msg,error=false)=>{const e=$("#toast");if(!e)return;e.textContent=msg;e.className=error?"show error":"show";clearTimeout(toast.t);toast.t=setTimeout(()=>e.className="",3200)};
const empty=msg=>`<div class="empty"><div class="empty-icon">◌</div><strong>${esc(msg)}</strong><span>Quando houver dados, eles aparecerão aqui automaticamente.</span></div>`;
const metric=(title,value,note="",icon="")=>`<article class="metric"><div class="metric-top"><span>${esc(title)}</span><b>${esc(icon)}</b></div><strong>${esc(value)}</strong><small>${esc(note)}</small></article>`;

function rowPermissions(){return[Permission.read(Role.user(user.$id)),Permission.update(Role.user(user.$id)),Permission.delete(Role.user(user.$id))]}
function ownerQuery(){return Query.equal("user_id",user.$id)}
async function listRows(table){const r=await db.listRows({databaseId:C.databaseId,tableId:table,queries:[ownerQuery(),Query.limit(100)]});return r.rows||[]}
async function createRow(table,data){return db.createRow({databaseId:C.databaseId,tableId:table,rowId:ID.unique(),data:{...data,user_id:user.$id},permissions:rowPermissions()})}
async function updateRow(table,id,data){return db.updateRow({databaseId:C.databaseId,tableId:table,rowId:id,data})}
async function deleteRow(table,id){return db.deleteRow({databaseId:C.databaseId,tableId:table,rowId:id})}
async function ensureProfile(){try{return await db.getRow({databaseId:C.databaseId,tableId:C.tables.profiles,rowId:user.$id})}catch{return db.createRow({databaseId:C.databaseId,tableId:C.tables.profiles,rowId:user.$id,data:{full_name:user.name||"Usuário",email:user.email||"",avatar_url:""},permissions:rowPermissions()})}}
async function ensureSettings(){const r=await listRows(C.tables.settings);if(r[0])return r[0];return createRow(C.tables.settings,{gross_salary:0,advance_pct:0,inss_pct:0,assist_pct:0,life_insurance:0,negocial:0})}
async function load(){const [transactions,goals,accounts,categories,bills,cards,settings]=await Promise.all([listRows(C.tables.transactions),listRows(C.tables.goals),listRows(C.tables.accounts),listRows(C.tables.categories),listRows(C.tables.bills),listRows(C.tables.cards),ensureSettings()]);state.transactions=transactions;state.goals=goals;state.accounts=accounts;state.categories=categories;state.bills=bills;state.cards=cards;state.settings=settings;seedDefaults()}
function seedDefaults(){const defaults=[["🍔","Alimentação"],["🚗","Transporte"],["🏠","Moradia"],["📚","Educação"],["🩺","Saúde"],["🎬","Lazer"],["🛍️","Compras pessoais"],["📱","Assinaturas"],["🧾","Contas"],["✈️","Viagens"],["🎁","Presentes"],["💼","Trabalho"],["🎯","Metas"],["⋯","Outros"]];if(!state.categories.length)state.categories=defaults.map(([icon,name])=>({$id:`local-${name}`,name,icon,monthly_limit:0}));}
function txTypeLabel(t){return({income:"Receita",expense:"Despesa",investment:"Investimento",transfer:"Transferência"}[t]||cap(t))}
function categoryName(v){return state.categories.find(c=>c.$id===v||c.name===v)?.name||v||"Sem Categoria"}
function currentMonth(){return today().slice(0,7)}
function monthTx(month=currentMonth()){return state.transactions.filter(t=>monthKey(t.transaction_date)===month)}
function totals(month=currentMonth()){const tx=monthTx(month),income=tx.filter(t=>t.type==="income").reduce((a,x)=>a+n(x.amount),0),expense=tx.filter(t=>t.type==="expense").reduce((a,x)=>a+n(x.amount),0),investment=tx.filter(t=>t.type==="investment").reduce((a,x)=>a+n(x.amount),0);const accountBalance=state.accounts.reduce((a,x)=>a+n(x.balance),0);return{tx,income,expense,investment,balance:accountBalance+income-expense-investment}}
function localKey(name){return`makaria_${name}_${user?.$id||"guest"}`}
function localGet(name,fallback={}){try{return JSON.parse(localStorage.getItem(localKey(name))||JSON.stringify(fallback))}catch{return fallback}}
function localSet(name,v){localStorage.setItem(localKey(name),JSON.stringify(v))}
function txMeta(id){const all=localGet("txmeta",{});return all[id]||{status:"Pago",establishment:"",note:"",tags:[],subcategory:"",recurring:false}}
function saveTxMeta(id,data){const all=localGet("txmeta",{});all[id]={...txMeta(id),...data};localSet("txmeta",all)}
function settingsPref(){return localGet("prefs",{hideValues:false,month:currentMonth(),salaryDay:5,mainAccount:"",mainCard:"",currency:"BRL",financialDay:1})}
function statusBadge(status){return`<span class="status ${status==="Pago"?"ok":status==="Vencido"?"bad":"warn"}">${esc(status)}</span>`}
function pageHeader(title,subtitle,action=""){return`<div class="card-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div>${action}</div>`}
function formOptions(items,valueKey="$id",labelKey="name",emptyLabel="Selecione"){return`<option value="">${emptyLabel}</option>`+items.filter(x=>x[valueKey]).map(x=>`<option value="${esc(x[valueKey])}">${esc(x[labelKey])}</option>`).join("")}
function nav(){const groups=[{title:"Principal",items:[["home","Início","⌂"],["transactions","Lançamentos","↕"]]},{title:"Planejamento",items:[["planning","Planejamento","◫"]]},{title:"Análises",items:[["analysis","Análises","◈"]]}];$("#mainNav").innerHTML=groups.map(g=>`<div class="nav-group"><small>${g.title}</small>${g.items.map(([p,t,i])=>`<button class="nav-btn ${state.page===p?"active":""}" data-page="${p}"><span>${i}</span>${t}</button>`).join("")}</div>`).join("");$$('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.sub=b.dataset.page==="planning"?"budget":b.dataset.page==="analysis"?"overview":"overview";render()})}
function shell(title,subtitle,body,crumb=""){$("#main").innerHTML=`<div class="page"><div class="page-title"><div><span class="eyebrow">${esc(crumb||"Makaria")}</span><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div></div>${body}</div>`}
function sectionTabs(items){return`<div class="subnav">${items.map(([id,label])=>`<button class="${state.sub===id?"active":""}" data-sub="${id}">${label}</button>`).join("")}</div>`}
function actionBar(){return`<div class="quick-actions"><button data-quick="expense">− Nova despesa</button><button data-quick="income">＋ Nova receita</button><button data-quick="bill">✓ Pagar conta</button><button data-quick="goal">🎯 Adicionar à meta</button><button data-quick="buy">🛍️ Posso comprar?</button></div>`}

function home(){const p=settingsPref(),t=totals(p.month),goalsSaved=state.goals.reduce((a,x)=>a+n(x.saved_amount),0),reserved=goalsSaved,pending=state.bills.filter(b=>(b.status||"Pendente")!=="Pago").reduce((a,b)=>a+n(b.amount),0),free=Math.max(0,t.balance-reserved-pending),salary=n(state.settings?.gross_salary),days=Math.max(1,daysUntilSalary()),daily=t.expense/Math.max(1,new Date().getDate()),week=Math.max(0,free/7),alert=mainAlert(t,pending),forecast=forecastBalance(t,pending),cards=state.cards.reduce((a,c)=>a+n(c.current_bill),0);
const cats={};t.tx.filter(x=>x.type==="expense").forEach(x=>{const k=categoryName(x.category);cats[k]=(cats[k]||0)+n(x.amount)});const catRows=state.categories.filter(c=>n(c.monthly_limit)>0).slice(0,6).map(c=>{const used=cats[c.name]||cats[c.$id]||0,limit=n(c.monthly_limit),pct=limit?used/limit*100:0;return`<div class="budget-row"><div><span>${esc(c.icon||"◈")} ${esc(c.name)}</span><b>${money(used)} / ${money(limit)}</b></div><div class="progress"><i class="${pct>100?"danger":pct>80?"warn":"ok"}" style="width:${Math.min(100,pct)}%"></i></div><small>${pct.toFixed(0)}% utilizado</small></div>`}).join("");
shell("Início",`Olá, ${user?.name||"Usuário"}! Veja como estão suas finanças em ${monthLabel(p.month)}.`,`<div class="hero-strip"><div><span class="eyebrow">Resumo inteligente</span><h2>Seu dinheiro, com clareza.</h2><p>${esc(alert.text)}</p></div><div class="hero-score">${healthScore(t,pending)}<small>saúde financeira</small></div></div>${actionBar()}<div class="metrics home-metrics">${metric("Saldo Total",money(t.balance),"Contas + resultado do período","R$")}${metric("Reservado",money(reserved),"Metas","🎯")}${metric("Contas Pendentes",money(pending),"Obrigações em aberto","◷")}${metric("Livre Para Usar",money(free),"Após reservas e contas","✓")}</div><div class="grid-3"><section class="card"><div class="card-head"><div><h2>Quanto posso gastar?</h2><p>Limite recomendado</p></div><span class="status ok">${free>0?"Dentro do plano":"Atenção"}</span></div><div class="big-number">${money(free/Math.max(1,days))}</div><p class="muted">por dia até o próximo recebimento · ${days} dia(s)</p><div class="split"><span>Semana</span><b>${money(week)}</b></div><div class="split"><span>Gasto médio/dia</span><b>${money(daily)}</b></div></section><section class="card">${pageHeader("Resumo do Mês","Entradas, saídas e previsão.")}${miniStat("Receitas",money(t.income),"positive")}${miniStat("Despesas pagas",money(t.expense),"negative")}${miniStat("Contas pendentes",money(pending),"warn")}${miniStat("Guardado",money(goalsSaved),"")}${miniStat("Saldo previsto",money(forecast),forecast<0?"negative":"positive")}</section><section class="card">${pageHeader("Cartões","Compromisso atual.")}${state.cards.length?state.cards.slice(0,3).map(c=>{const lim=n(c.credit_limit),bill=n(c.current_bill),pct=lim?bill/lim*100:0;return`<div class="card-mini"><div><b>${esc(c.name)}</b><small>Fatura ${money(bill)}</small></div><strong>${pct.toFixed(0)}%</strong></div><div class="progress"><i class="${pct>90?"danger":pct>80?"warn":"ok"}" style="width:${Math.min(100,pct)}%"></i></div>`}).join(""):empty("Nenhum cartão cadastrado.")}</section></div><div class="grid-2"><section class="card">${pageHeader("Orçamento por Categoria","Veja onde você está acima do limite.")}${catRows||empty("Defina limites nas categorias para acompanhar seu orçamento.")}</section><section class="card">${pageHeader("Próximas Contas","Até cinco próximos compromissos.")}${upcomingBills().map(b=>`<div class="bill-row"><div><b>${esc(b.name)}</b><small>${esc(categoryName(b.category))} · ${dueText(b.due_day)}</small></div><strong>${money(b.amount)}</strong><button class="mini-btn" data-pay-bill="${b.$id}">Marcar paga</button></div>`).join("")||empty("Nenhuma conta pendente.")}</section></div><section class="card prediction ${forecast<0?"danger-card":""}"><span class="eyebrow">Previsão financeira</span><h2>${esc(forecast<0?`Existe risco de seu saldo ficar negativo. Reduza aproximadamente ${money(Math.abs(forecast)/4)} por semana.`:`Mantendo seu ritmo atual, você terminará o mês com aproximadamente ${money(forecast)}.`)}</h2></section><section class="card alert-card"><span class="eyebrow">Ação mais importante agora</span><h2>${esc(alert.text)}</h2><button class="secondary" data-alert-action="${alert.action}">${esc(alert.button)}</button></section>`);bindQuick();$$('[data-pay-bill]').forEach(b=>b.onclick=()=>payBill(b.dataset.payBill));$$('[data-alert-action]').forEach(b=>b.onclick=()=>{state.page=b.dataset.alertAction;render()})}
function miniStat(a,b,c){return`<div class="mini-stat"><span>${a}</span><b class="${c}">${b}</b></div>`}
function businessDayOfMonth(year,month,ordinal=5){let d=new Date(year,month,1);let count=0;while(d.getMonth()===month){const wd=d.getDay();if(wd!==0&&wd!==6){count++;if(count===ordinal)return d}d.setDate(d.getDate()+1)}return new Date(year,month,ordinal)}
function nextSalaryReceipt(){const s=state.settings||{},p=settingsPref(),hasAdvance=p.hasAdvance!==false && n(s.advance_pct)>0,advancePct=hasAdvance?Math.max(0,Math.min(100,n(s.advance_pct))):0,now=new Date();const gross=n(s.gross_salary);const advance=gross*advancePct/100;const mandatory=gross*n(s.inss_pct)/100+gross*n(s.assist_pct)/100+n(s.life_insurance)+n(s.negocial);const extra=localGet("salaryitems",{income:[],deduction:[]}).deduction.reduce((a,x)=>a+salaryValue(x,gross),0);const final=Math.max(0,gross-advance-mandatory-extra);let advanceDay=Math.max(1,Math.min(28,Number(p.advanceDay)||20));let advanceDate=new Date(now.getFullYear(),now.getMonth(),advanceDay);let finalDate=businessDayOfMonth(now.getFullYear(),now.getMonth()+1,5);if(advanceDate<now){advanceDate=new Date(now.getFullYear(),now.getMonth()+1,advanceDay);finalDate=businessDayOfMonth(now.getFullYear(),now.getMonth()+1,5)}return{gross,advancePct,advance,final,mandatory,extra,advanceDate,finalDate,total:gross-mandatory-extra}}
function daysUntilSalary(){const s=nextSalaryReceipt(),now=new Date(),dates=[s.advanceDate,s.finalDate].filter(d=>d>now).sort((a,b)=>a-b);return Math.max(1,Math.ceil(((dates[0]||s.finalDate)-now)/86400000))}
function dueText(day){const now=new Date(),d=Math.max(1,Number(day)||1),target=new Date(now.getFullYear(),now.getMonth(),d);if(target<now)target.setMonth(target.getMonth()+1);const diff=Math.ceil((target-now)/86400000);return diff===0?"vence hoje":diff===1?"vence amanhã":`vence em ${diff} dias`}
function upcomingBills(){return state.bills.filter(b=>(b.status||"Pendente")!=="Pago").sort((a,b)=>Number(a.due_day)-Number(b.due_day)).slice(0,5)}
function forecastBalance(t,pending){const days=new Date().getDate(),daysMonth=new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate(),avg=t.expense/Math.max(1,days),remaining=Math.max(0,daysMonth-days);return t.balance-pending-avg*remaining}
function mainAlert(t,pending){const cats={};t.tx.filter(x=>x.type==="expense").forEach(x=>cats[categoryName(x.category)]=(cats[categoryName(x.category)]||0)+n(x.amount));const over=state.categories.map(c=>({c,v:cats[c.name]||0,l:n(c.monthly_limit)})).filter(x=>x.l&&x.v>x.l).sort((a,b)=>(b.v-b.l)-(a.v-a.l))[0];if(over)return{text:`Sua categoria ${over.c.name} ultrapassou o limite em ${money(over.v-over.l)}.`,action:"planning",button:"Revisar orçamento"};if(upcomingBills().length>=3)return{text:"Três ou mais contas estão próximas do vencimento. Organize as saídas antes do próximo recebimento.",action:"planning",button:"Ver contas"};if(t.expense>t.income&&t.income>0)return{text:"Suas despesas já superaram as receitas do período. Reduza gastos variáveis antes de assumir novas parcelas.",action:"transactions",button:"Revisar lançamentos"};return{text:"Seu próximo passo é registrar os gastos do dia e acompanhar o limite disponível.",action:"transactions",button:"Registrar despesa"}}
function healthScore(t,pending){let s=70;if(t.income>0)s+=Math.max(-15,Math.min(15,(t.income-t.expense)/t.income*30));if(pending>t.income*.3)s-=15;if(t.expense>t.income&&t.income)s-=15;return Math.max(0,Math.min(100,Math.round(s)))}

function transactions(){const rows=[...state.transactions].sort((a,b)=>String(b.transaction_date).localeCompare(String(a.transaction_date)));const inc=rows.filter(x=>x.type==="income").reduce((a,x)=>a+n(x.amount),0),exp=rows.filter(x=>x.type==="expense").reduce((a,x)=>a+n(x.amount),0),pend=rows.filter(x=>txMeta(x.$id).status!=="Pago").filter(x=>x.type==="expense").reduce((a,x)=>a+n(x.amount),0);shell("Lançamentos","Toda a movimentação financeira em um só lugar.",`${sectionTabs([["overview","Visão geral"],["list","Todos os lançamentos"],["templates","Modelos"]])}<div class="metrics">${metric("Total Recebido",money(inc),"Período atual","↗")}${metric("Total Gasto",money(exp),"Período atual","↘")}${metric("Diferença",money(inc-exp),"Entradas − saídas","=" )}${metric("Pendentes",money(pend),"Despesas não pagas","◷")}</div>${state.sub==="templates"?templatesSection():state.sub==="overview"?transactionOverview(rows):transactionList(rows)}`);bindTransactionActions()}
function transactionOverview(rows){return`<section class="card">${pageHeader("Busca e filtros","Encontre qualquer lançamento rapidamente.",`<button class="primary" data-quick="expense">+ Novo lançamento</button>`)}<div class="searchbar"><input id="txSearch" placeholder="Pesquisar descrição, categoria, estabelecimento, valor ou etiqueta..."><select id="txType"><option value="">Todos os tipos</option><option value="income">Receita</option><option value="expense">Despesa</option><option value="transfer">Transferência</option><option value="investment">Investimento</option></select><select id="txStatus"><option value="">Todos os status</option><option>Pago</option><option>Pendente</option></select></div><div id="txResults">${groupedTx(rows)}</div></section>`}
function transactionList(rows){return`<section class="card">${pageHeader("Lançamentos","Agrupados por data.",`<button class="primary" data-quick="expense">+ Adicionar</button>`)}${groupedTx(rows)}</section>`}
function groupedTx(rows){if(!rows.length)return empty("Nenhum lançamento cadastrado.");const groups={};rows.forEach(x=>(groups[x.transaction_date]??=[]).push(x));return Object.entries(groups).sort((a,b)=>b[0].localeCompare(a[0])).map(([d,arr])=>`<div class="tx-day"><h3>${d===today()?"Hoje":dateBR(d)}</h3>${arr.map(x=>txRow(x)).join("")}</div>`).join("")}
function txRow(x){const m=txMeta(x.$id);return`<button class="tx-row" data-tx-detail="${x.$id}"><span class="tx-icon">${esc(categoryIcon(x.category))}</span><span class="tx-main"><b>${esc(x.description||txTypeLabel(x.type))}</b><small>${esc(categoryName(x.category))}${m.establishment?` · ${esc(m.establishment)}`:""}${x.installments>1?` · ${x.installment_number||1}/${x.installments}`:""}</small></span><span class="tx-side">${statusBadge(m.status||"Pago")}<strong class="${x.type==='income'?"positive":x.type==='expense'?"negative":""}">${x.type==='income'?"+":x.type==='expense'?"−":""}${money(x.amount)}</strong></span></button>`}
function categoryIcon(v){return state.categories.find(c=>c.$id===v||c.name===v)?.icon||"◈"}
function bindTransactionActions(){$$('[data-tx-detail]').forEach(b=>b.onclick=()=>transactionDetail(b.dataset.txDetail));bindQuick();const s=$("#txSearch"),ty=$("#txType"),st=$("#txStatus");const apply=()=>{const q=(s?.value||"").toLowerCase();let r=state.transactions.filter(x=>{const m=txMeta(x.$id),text=[x.description,x.category,m.establishment,m.note,(m.tags||[]).join(" "),x.amount].join(" ").toLowerCase();return(!q||text.includes(q))&&(!ty?.value||x.type===ty.value)&&(!st?.value||m.status===st.value)});if($("#txResults"))$("#txResults").innerHTML=groupedTx(r)};if(s)s.oninput=apply;if(ty)ty.onchange=apply;if(st)st.onchange=apply}
function transactionDetail(id){const x=state.transactions.find(t=>t.$id===id);if(!x)return;const m=txMeta(id);modal(`<div class="modal-head"><div><span class="eyebrow">Detalhes do lançamento</span><h2>${esc(x.description||txTypeLabel(x.type))}</h2></div><button data-close>×</button></div><div class="detail-grid"><div><small>Tipo</small><b>${txTypeLabel(x.type)}</b></div><div><small>Valor</small><b>${money(x.amount)}</b></div><div><small>Data</small><b>${dateBR(x.transaction_date)}</b></div><div><small>Categoria</small><b>${esc(categoryName(x.category))}</b></div><div><small>Forma de pagamento</small><b>${esc(x.payment_method||"—")}</b></div><div><small>Status</small><b>${statusBadge(m.status||"Pago")}</b></div><div><small>Estabelecimento</small><b>${esc(m.establishment||"—")}</b></div><div><small>Etiquetas</small><b>${esc((m.tags||[]).join(", ")||"—")}</b></div></div><div class="modal-actions"><button class="secondary" data-edit-tx="${id}">Editar</button><button class="secondary" data-duplicate-tx="${id}">Duplicar</button><button class="secondary" data-paid-tx="${id}">${m.status==="Pago"?"Marcar pendente":"Marcar como pago"}</button><button class="danger-btn" data-delete-detail="${id}">Excluir</button></div>`);$("[data-edit-tx]").onclick=()=>editTransaction(id);$("[data-duplicate-tx]").onclick=()=>duplicateTransaction(x);$("[data-paid-tx]").onclick=async()=>{saveTxMeta(id,{status:m.status==="Pago"?"Pendente":"Pago"});closeModal();render()};$("[data-delete-detail]").onclick=()=>deleteTransaction(id)}
function editTransaction(id){const x=state.transactions.find(t=>t.$id===id),m=txMeta(id);modal(`<div class="modal-head"><h2>Editar lançamento</h2><button data-close>×</button></div><form id="editTx" class="form-grid"><label>Valor<input name="amount" type="number" step="0.01" value="${n(x.amount)}" required></label><label>Categoria<select name="category">${formOptions(state.categories,"name","name","")}</select></label><label>Data<input name="transaction_date" type="date" value="${esc(x.transaction_date)}"></label><label>Pagamento<select name="payment_method"><option>${esc(x.payment_method||"Pix")}</option><option>Pix</option><option>Cartão de Crédito</option><option>Cartão de Débito</option><option>Dinheiro</option><option>Boleto</option></select></label><label class="wide">Descrição<input name="description" value="${esc(x.description||"")}"></label><label>Estabelecimento<input name="establishment" value="${esc(m.establishment||"")}"></label><label>Status<select name="status"><option ${m.status==="Pago"?"selected":""}>Pago</option><option ${m.status!=="Pago"?"selected":""}>Pendente</option></select></label><div class="wide actions"><button class="primary">Salvar alterações</button></div></form>`);$("#editTx").onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.amount=n(d.amount);const {establishment,status}=d;delete d.establishment;delete d.status;try{await updateRow(C.tables.transactions,id,d);saveTxMeta(id,{establishment,status});toast("Lançamento atualizado.");closeModal();await load();render()}catch(err){toast(err.message,true)}}}
async function duplicateTransaction(x){const d={type:x.type,amount:n(x.amount),category:x.category,description:`${x.description||txTypeLabel(x.type)} (cópia)`,transaction_date:today(),payment_method:x.payment_method||"Pix",installments:x.installments||1,installment_number:1};try{await createRow(C.tables.transactions,d);toast("Lançamento duplicado.");closeModal();await load();render()}catch(e){toast(e.message,true)}}
async function deleteTransaction(id){if(!confirm("Excluir este lançamento?"))return;try{await deleteRow(C.tables.transactions,id);const all=localGet("txmeta",{});delete all[id];localSet("txmeta",all);toast("Lançamento excluído.");closeModal();await load();render()}catch(e){toast(e.message,true)}}

function planning(){const tabs=[["budget","Orçamento"],["calendar","Calendário"],["accounts","Contas"],["cards","Cartões"],["goals","Metas"],["simulations","Simulações"]];shell("Planejamento","Organize o presente e teste decisões antes de tomar decisões reais.",sectionTabs(tabs)+(state.sub==="budget"?budgetSection():state.sub==="calendar"?calendarSection():state.sub==="accounts"?accountsSection():state.sub==="cards"?cardsSection():state.sub==="goals"?goalsSection():simulationSection()),"Planejamento")}
function budgetSection(){const t=totals(),spent={};t.tx.filter(x=>x.type==="expense").forEach(x=>spent[categoryName(x.category)]=(spent[categoryName(x.category)]||0)+n(x.amount));const salary=n(state.settings?.gross_salary),planned=state.categories.reduce((a,c)=>a+n(c.monthly_limit),0),free=Math.max(0,salary-t.expense-state.bills.filter(b=>b.status!=="Pago").reduce((a,b)=>a+n(b.amount),0));return`<div class="metrics">${metric("Renda Prevista",money(salary),"Salário configurado","↗")}${metric("Planejado",money(planned),"Limites das categorias","◫")}${metric("Realizado",money(t.expense),"Despesas do mês","✓")}${metric("Dinheiro Livre",money(free),"Estimativa","◎")}</div><section class="card">${pageHeader("Planejado × Realizado × Previsto","Acompanhe cada categoria sem precisar atualizar percentuais manualmente.")}${state.categories.filter(c=>n(c.monthly_limit)>0).map(c=>{const p=n(c.monthly_limit),r=spent[c.name]||0,forecast=r+(r/Math.max(1,new Date().getDate()))*Math.max(0,new Date(new Date().getFullYear(),new Date().getMonth()+1,0).getDate()-new Date().getDate());return`<div class="triple-row"><div><b>${esc(c.name)}</b><small>Planejado ${money(p)} · Realizado ${money(r)} · Previsto ${money(forecast)}</small></div><div class="progress"><i class="${forecast>p?"danger":forecast>p*.8?"warn":"ok"}" style="width:${Math.min(100,forecast/p*100)}%"></i></div></div>`}).join("")||empty("Defina limites nas categorias para começar o planejamento.")}</section><section class="grid-2"><div class="card">${pageHeader("Distribuição do Dinheiro","Uma visão prática da renda.")}${distribution(salary,t.expense,free)}</div><div class="card">${pageHeader("Fechamento Mensal","Resumo do que importa.")}${miniStat("Renda total",money(t.income),"")}${miniStat("Despesas",money(t.expense),"")}${miniStat("Economia",money(t.income-t.expense),t.income>=t.expense?"positive":"negative")}${miniStat("Destino às metas",money(state.goals.reduce((a,g)=>a+n(g.saved_amount),0)),"")}</div></div>`}
function distribution(salary,expense,free){const essential=state.bills.filter(b=>b.status!=="Pago").reduce((a,b)=>a+n(b.amount),0);const non=Math.max(0,expense-essential);return`<div class="distribution"><div><span>Essenciais</span><b>${money(essential)}</b></div><div><span>Não essenciais</span><b>${money(non)}</b></div><div><span>Metas</span><b>${money(state.goals.reduce((a,g)=>a+n(g.saved_amount),0))}</b></div><div><span>Livre</span><b>${money(free)}</b></div></div>`}
function calendarSection(){const now=new Date(),m=monthKey(today()),days=new Date(now.getFullYear(),now.getMonth()+1,0).getDate(),first=new Date(now.getFullYear(),now.getMonth(),1).getDay(),events={};state.bills.forEach(b=>{const d=Number(b.due_day);if(d)events[d]=(events[d]||[]).concat([{type:"bill",title:b.name,value:n(b.amount)}])});monthTx(m).forEach(t=>{const d=Number(String(t.transaction_date).slice(8,10));events[d]=(events[d]||[]).concat([{type:t.type,title:t.description||txTypeLabel(t.type),value:n(t.amount)}])});let cells="";for(let i=0;i<first;i++)cells+=`<div class="cal-cell muted-cell"></div>`;for(let d=1;d<=days;d++){const ev=events[d]||[];cells+=`<div class="cal-cell"><b>${d}</b>${ev.slice(0,3).map(e=>`<span class="cal-dot ${e.type}">${esc(e.title.slice(0,14))}</span>`).join("")}</div>`}return`<div class="calendar-head"><h2>${cap(monthLabel(m))}</h2><span class="status">Mapa de calor financeiro</span></div><section class="card calendar-card"><div class="calendar-grid">${cells}</div></section><section class="card">${pageHeader("Resumo do dia","Selecione um dia para analisar compromissos e movimentações.")}${Object.entries(events).sort((a,b)=>Number(a[0])-Number(b[0])).slice(0,10).map(([d,ev])=>`<div class="day-summary"><b>Dia ${d}</b><span>${ev.length} evento(s)</span><strong>${money(ev.reduce((a,x)=>a+n(x.value),0))}</strong></div>`).join("")||empty("Nenhum compromisso no mês.")}</section>`}
function accountsSection(){return`<section class="card">${pageHeader("Nova Conta","Conta-corrente, poupança, carteira, dinheiro ou investimento.")}<form id="accountForm" class="form-grid"><label>Nome<input name="name" required placeholder="Ex.: Nubank, Santander, Carteira"></label><label>Saldo Atual<input name="balance" type="number" step="0.01" value="0"></label><label>Dia de Vencimento<input name="due_day" type="number" min="1" max="31"></label><label>Recorrente<select name="recurring"><option value="false">Não</option><option value="true">Sim</option></select></label><div class="wide actions"><button class="primary">Adicionar Conta</button></div></form></section><section class="grid-3">${state.accounts.map(a=>`<article class="card account-card"><span class="eyebrow">Conta</span><h2>${esc(a.name)}</h2><strong>${money(a.balance)}</strong><small>Entradas e saídas podem ser conciliadas com os lançamentos.</small></article>`).join("")||`<div class="card">${empty("Nenhuma conta cadastrada.")}</div>`}</section><section class="card">${pageHeader("Conciliação Manual","Compare o saldo calculado com o saldo real informado por você.")}<form id="reconcileForm" class="form-grid"><label>Conta<select name="account">${formOptions(state.accounts)}</select></label><label>Saldo informado<input name="real" type="number" step="0.01"></label><div class="wide actions"><button class="secondary">Comparar saldo</button></div></form><div id="reconcileResult"></div></section>`}
function creditCardBill(card){
  const close=Number(card?.closing_day)||0;
  const now=new Date();
  const end=close?new Date(now.getFullYear(),now.getMonth(),close,23,59,59):new Date(now.getFullYear(),now.getMonth()+1,0,23,59,59);
  let start;
  if(close){
    if(now.getDate()>close) start=new Date(now.getFullYear(),now.getMonth(),close+1,0,0,0);
    else start=new Date(now.getFullYear(),now.getMonth()-1,close+1,0,0,0);
  }else start=new Date(now.getFullYear(),now.getMonth(),1,0,0,0);
  return state.transactions.filter(t=>{
    const pm=String(t.payment_method||"").toLowerCase().normalize("NFD").replace(/[\\u0300-\\u036f]/g,"");
    if(!pm.includes("cartao de credito")) return false;
    const raw=String(t.transaction_date||"").slice(0,10);
    const d=new Date(`${raw}T23:59:59`);
    return !Number.isNaN(d.getTime())&&d>=start&&d<=end;
  }).reduce((a,t)=>a+n(t.amount),0);
}
function cardsSection(){return`<section class="card">${pageHeader("Novo Cartão","Controle limite, fechamento e vencimento. A fatura é calculada automaticamente a partir dos lançamentos no Cartão de Crédito.")}<form id="cardForm" class="form-grid"><label>Nome<input name="name" required placeholder="Ex.: Nubank Platinum"></label><label>Limite<input name="credit_limit" type="number" step="0.01"></label><input type="hidden" name="current_bill" value="0"><label>Dia de Fechamento<input name="closing_day" type="number" min="1" max="31"></label><label>Dia de Vencimento<input name="due_day" type="number" min="1" max="31"></label><div class="wide notice">A fatura não é preenchida manualmente. Ela será atualizada conforme você registrar despesas usando <b>Cartão de Crédito</b> nos Lançamentos.</div><div class="wide actions"><button class="primary">Adicionar Cartão</button></div></form></section><section class="card-grid">${state.cards.map(c=>{const lim=n(c.credit_limit),bill=creditCardBill(c),pct=lim?bill/lim*100:0;return`<article class="bank-card"><div><span>${esc(c.name)}</span><b>MAKARIA</b></div><div class="card-limit">${money(bill)}<small>fatura calculada</small></div><div class="card-foot"><span>Limite ${money(lim)}</span><span>Disponível ${money(Math.max(0,lim-bill))}</span></div><div class="progress"><i class="${pct>90?"danger":pct>80?"warn":"ok"}" style="width:${Math.min(100,pct)}%"></i></div><small>Fecha dia ${c.closing_day||"—"} · vence dia ${c.due_day||"—"}</small></article>`}).join("")||empty("Nenhum cartão cadastrado.")}</section><section class="card">${pageHeader("Raio-X da Fatura","Compras e parcelas registradas no crédito.")}<div class="grid-3">${state.cards.map(c=>`<div class="insight-box"><b>${esc(c.name)}</b><span>Fatura atual</span><strong>${money(creditCardBill(c))}</strong><small>Valor calculado automaticamente a partir dos lançamentos no Cartão de Crédito.</small></div>`).join("")||empty("Cadastre um cartão para ver o raio-X.")}</div></section>`}
function goalsSection(){return`<section class="card">${pageHeader("Nova Meta","Reserva, viagem, faculdade, veículo ou qualquer objetivo.")}<form id="goalForm" class="form-grid"><label>Nome da Meta<input name="name" required placeholder="Ex.: Reserva de Emergência"></label><label>Valor Objetivo<input name="target_amount" type="number" step="0.01" required></label><label>Valor Já Guardado<input name="saved_amount" type="number" step="0.01" value="0"></label><label>Data Alvo<input name="target_date" type="date"></label><label class="wide">Descrição<input name="description" placeholder="Detalhes da meta"></label><div class="wide actions"><button class="primary">Criar Meta</button></div></form></section><section class="goal-grid">${state.goals.map(g=>{const p=n(g.target_amount)?Math.min(100,n(g.saved_amount)/n(g.target_amount)*100):0;const months=g.target_date?Math.max(1,Math.ceil((new Date(`${g.target_date}T12:00:00`)-new Date())/(86400000*30))):0;const need=months?Math.max(0,n(g.target_amount)-n(g.saved_amount))/months:0;return`<article class="card goal-card"><div class="card-head"><div><span class="goal-icon">🎯</span><h2>${esc(g.name)}</h2></div><span class="status">${p.toFixed(0)}%</span></div><div class="big-number">${money(g.saved_amount)}</div><p class="muted">de ${money(g.target_amount)}</p><div class="progress"><i class="ok" style="width:${p}%"></i></div><div class="split"><span>Restante</span><b>${money(Math.max(0,n(g.target_amount)-n(g.saved_amount)))}</b></div><div class="split"><span>Contribuição sugerida</span><b>${months?money(need):"Defina um prazo"}</b></div></article>`}).join("")||`<div class="card">${empty("Nenhuma meta cadastrada.")}</div>`}</section>`}
function simulationSection(){return`<section class="grid-2"><section class="card">${pageHeader("Posso comprar?","Teste uma compra sem alterar seus dados reais.")}<form id="buyForm" class="form-grid"><label class="wide">Produto<input name="name" placeholder="Ex.: Notebook"></label><label>Preço<input name="price" type="number" step="0.01"></label><label>Parcelas<input name="installments" type="number" min="1" value="1"></label><label>Juros (%)<input name="interest" type="number" step="0.01" value="0"></label><label>Pagamento<select name="method"><option>Cartão</option><option>À vista</option></select></label><div class="wide actions"><button class="primary">Simular</button></div></form><div id="buyResult"></div></section><section class="card">${pageHeader("Gêmeo Financeiro","Experimente cenários sem modificar os lançamentos reais.")}<div class="scenario-buttons"><button data-scenario="conservative">Conservador</button><button data-scenario="probable">Provável</button><button data-scenario="optimistic">Otimista</button></div><div id="scenarioResult" class="scenario-result">Escolha um cenário para projetar saldo, faturas e dinheiro livre.</div></section></section>`}

function analysis(){const tabs=[["overview","Visão geral"],["flow","Fluxo do dinheiro"],["categories","Categorias"],["balance","Evolução do saldo"],["patterns","Padrões"],["leaks","Vazamentos"],["health","Saúde financeira"],["reports","Relatórios"]];shell("Análises","Gráficos, padrões e previsões a partir dos dados registrados.",sectionTabs(tabs)+(state.sub==="overview"?analysisOverview():state.sub==="flow"?flowAnalysis():state.sub==="categories"?categoryAnalysis():state.sub==="balance"?balanceAnalysis():state.sub==="patterns"?patternsAnalysis():state.sub==="leaks"?leaksAnalysis():state.sub==="health"?healthAnalysis():reportsAnalysis()),"Análises")}
function analysisOverview(){const t=totals(),prevMonth=new Date();prevMonth.setMonth(prevMonth.getMonth()-1);const prev=monthKey(prevMonth.toISOString().slice(0,10)),pt=totals(prev),saving=t.income-t.expense,variation=pt.expense?saving/pt.expense*100:0;return`<div class="metrics">${metric("Total Recebido",money(t.income),"Mês atual","↗")}${metric("Total Gasto",money(t.expense),"Mês atual","↘")}${metric("Economia",money(saving),"Receitas − despesas","✓")}${metric("Variação",`${variation.toFixed(1)}%`,`vs. período anterior`,variation>=0?"↑":"↓")}</div><section class="grid-2"><div class="card">${pageHeader("Fluxo do Dinheiro","Receitas, essenciais, cartão, lazer, metas e saldo.")}${flowBars(t)}</div><div class="card">${pageHeader("Despesas por Categoria","Ordenadas por impacto.")}${categoryBars(t)}</div></div><section class="card">${pageHeader("Evolução e projeção","O saldo atual comparado ao comportamento do mês.")}${balanceChart(t)}</section>`}
function flowBars(t){const essential=state.bills.filter(b=>b.status!=="Pago").reduce((a,b)=>a+n(b.amount),0),goal=state.goals.reduce((a,g)=>a+n(g.saved_amount),0),rows=[["Receitas",t.income],["Despesas essenciais",essential],["Cartão",state.cards.reduce((a,c)=>a+n(c.current_bill),0)],["Lazer",monthTx().filter(x=>categoryName(x.category)==="Lazer").reduce((a,x)=>a+n(x.amount),0)],["Metas",goal],["Saldo",t.balance]];const max=Math.max(1,...rows.map(x=>x[1]));return rows.map(([k,v])=>`<div class="bar-row"><div><span>${k}</span><b>${money(v)}</b></div><div class="bar"><i style="width:${Math.max(3,v/max*100)}%"></i></div></div>`).join("")}
function categoryBars(t){const o={};t.tx.filter(x=>x.type==="expense").forEach(x=>o[categoryName(x.category)]=(o[categoryName(x.category)]||0)+n(x.amount));const a=Object.entries(o).sort((x,y)=>y[1]-x[1]),max=a[0]?.[1]||1;return a.map(([k,v])=>`<div class="bar-row"><div><span>${esc(k)}</span><b>${money(v)} · ${(v/t.expense*100||0).toFixed(1)}%</b></div><div class="bar"><i style="width:${v/max*100}%"></i></div></div>`).join("")||empty("Ainda não há despesas.")}
function balanceChart(t){const days=new Date().getDate(),avg=t.expense/Math.max(1,days);return`<div class="chart-faux"><div class="chart-line"><span style="height:${Math.min(92,Math.max(8,50+t.balance/Math.max(1,t.income)*35))}%"></span><span style="height:${Math.min(92,Math.max(8,50+(t.balance-avg*7)/Math.max(1,t.income)*35))}%"></span><span style="height:${Math.min(92,Math.max(8,50+(t.balance-avg*14)/Math.max(1,t.income)*35))}%"></span><span style="height:${Math.min(92,Math.max(8,50+(t.balance-avg*21)/Math.max(1,t.income)*35))}%"></span><span style="height:${Math.min(92,Math.max(8,50+(t.balance-avg*30)/Math.max(1,t.income)*35))}%"></span></div><div class="chart-labels"><span>Hoje</span><span>+7d</span><span>+14d</span><span>+21d</span><span>Fim do mês</span></div></div>`}
function flowAnalysis(){return`<section class="card">${pageHeader("Fluxo do dinheiro","As linhas representam a concentração de valores por etapa.")}${flowBars(totals())}</section>`}
function categoryAnalysis(){return`<section class="card">${pageHeader("Despesas por categoria","Valor, porcentagem e participação.")}${categoryBars(totals())}</section>`}
function balanceAnalysis(){return`<section class="card">${pageHeader("Evolução do saldo","Projeção de 30 dias com o ritmo atual.")}${balanceChart(totals())}<p class="muted">A projeção é uma estimativa baseada nas despesas já registradas; não é uma garantia de saldo futuro.</p></section>`}
function patternsAnalysis(){const tx=monthTx().filter(x=>x.type==="expense"),byDay={};tx.forEach(x=>{const d=new Date(`${x.transaction_date}T12:00:00`).toLocaleDateString("pt-BR",{weekday:"long"});byDay[d]=(byDay[d]||0)+n(x.amount)});const topDay=Object.entries(byDay).sort((a,b)=>b[1]-a[1])[0];const top=tx.sort((a,b)=>n(b.amount)-n(a.amount))[0];return`<div class="metrics">${metric("Dia que mais gasta",topDay?cap(topDay[0]):"—",topDay?money(topDay[1]):"Sem dados","◷")}${metric("Maior despesa",top?money(top.amount):"—",top?.description||"Sem dados","↑")}${metric("Gasto médio/dia",money(totals().expense/Math.max(1,new Date().getDate())),"Mês atual","∅")}${metric("Lançamentos",tx.length,"Despesas do mês","#")}</div><section class="card">${pageHeader("Padrões encontrados","Observações automáticas baseadas no histórico.")}${topDay?`<div class="insight"><span class="insight-icon">✦</span><div><b>${cap(topDay[0])} concentra seus maiores gastos.</b><p class="muted">Nesse dia da semana, os lançamentos somam ${money(topDay[1])} neste mês.</p></div></div>`:empty("Registre mais despesas para identificar padrões.")}</section>`}
function leaksAnalysis(){const tx=monthTx().filter(x=>x.type==="expense"),small=tx.filter(x=>n(x.amount)<20),subs=state.bills.filter(b=>String(b.category||"").toLowerCase().includes("assin"));return`<div class="grid-2"><section class="card">${pageHeader("Pequenos gastos repetidos","Valores abaixo de R$ 20 que podem passar despercebidos.")}${small.length?`<div class="leak-number">${small.length}</div><p>compras abaixo de R$ 20, somando <b>${money(small.reduce((a,x)=>a+n(x.amount),0))}</b>.</p>`:empty("Nenhum vazamento desse tipo identificado.")}</section><section class="card">${pageHeader("Assinaturas e recorrências","Contas que podem merecer revisão.")}${subs.length?subs.map(x=>`<div class="split"><span>${esc(x.name)}</span><b>${money(x.amount)}</b></div>`).join(""):empty("Nenhuma assinatura identificada.")}</section></div>`}
function healthAnalysis(){const t=totals(),pending=state.bills.filter(b=>b.status!=="Pago").reduce((a,b)=>a+n(b.amount),0),score=healthScore(t,pending);return`<section class="card health-card"><div class="health-score">${score}</div><div><span class="eyebrow">Nota de saúde financeira</span><h2>${score>=80?"Boa organização financeira":score>=60?"Atenção a alguns pontos":"Momento de reorganização"}</h2><p class="muted">A nota considera orçamento, contas, comprometimento, cartão e metas com base nos dados disponíveis.</p></div></section><div class="grid-2"><div class="card">${miniStat("Contas pendentes",money(pending),pending>t.income*.3?"negative":"")}${miniStat("Comprometimento",t.income?`${(t.expense/t.income*100).toFixed(1)}%`:"0,0%","")}${miniStat("Metas cadastradas",state.goals.length,"positive")}</div><div class="card"><h2>Como melhorar</h2><ul class="clean-list"><li>Registre todas as despesas.</li><li>Defina limites para as categorias principais.</li><li>Evite novas parcelas quando o orçamento estiver apertado.</li><li>Mantenha uma meta de reserva de emergência.</li></ul></div></div>`}
function reportRows(type, period){
  const tx=periodTx(period), income=tx.filter(x=>x.type==="income"), expense=tx.filter(x=>x.type==="expense"), totalIn=income.reduce((a,x)=>a+n(x.amount),0), totalOut=expense.reduce((a,x)=>a+n(x.amount),0);
  if(type==="Resumo mensal") return {title:"Resumo financeiro", headers:["Indicador","Valor"], rows:[["Receitas",money(totalIn)],["Despesas",money(totalOut)],["Economia",money(totalIn-totalOut)],["Lançamentos",String(tx.length)],["Contas pendentes",money(state.bills.filter(b=>b.status!=="Pago").reduce((a,b)=>a+n(b.amount),0))],["Metas acumuladas",money(state.goals.reduce((a,g)=>a+n(g.saved_amount),0))]]};
  if(type==="Gastos por categoria") {const m={};expense.forEach(x=>m[categoryName(x.category)]=(m[categoryName(x.category)]||0)+n(x.amount));const rows=Object.entries(m).sort((a,b)=>b[1]-a[1]).map(([k,v])=>[k,money(v),totalOut?`${(v/totalOut*100).toFixed(1)}%`:"0,0%"]);return {title:"Gastos por categoria",headers:["Categoria","Valor","Participação"],rows};}
  if(type==="Receitas x despesas") return {title:"Receitas x despesas",headers:["Data","Tipo","Descrição","Categoria","Valor"],rows:tx.sort((a,b)=>String(a.transaction_date).localeCompare(String(b.transaction_date))).map(x=>[dateBR(x.transaction_date),txTypeLabel(x.type),x.description||txTypeLabel(x.type),categoryName(x.category),money(x.amount)])};
  if(type==="Contas e vencimentos") return {title:"Contas e vencimentos",headers:["Conta","Categoria","Valor","Vencimento","Status"],rows:state.bills.map(b=>[b.name,categoryName(b.category),money(b.amount),String(b.due_day),b.status||"Pendente"])};
  if(type==="Cartões") return {title:"Resumo dos cartões",headers:["Cartão","Limite","Fatura atual","Limite disponível","Fechamento","Vencimento"],rows:state.cards.map(c=>{const lim=n(c.credit_limit),bill=n(c.current_bill);return[c.name,money(lim),money(bill),money(Math.max(0,lim-bill)),String(c.closing_day||"—"),String(c.due_day||"—")]})};
  if(type==="Metas") return {title:"Metas financeiras",headers:["Meta","Objetivo","Guardado","Progresso","Prazo"],rows:state.goals.map(g=>{const target=n(g.target_amount),saved=n(g.saved_amount);return[g.name,money(target),money(saved),target?`${Math.min(100,saved/target*100).toFixed(1)}%`:"0,0%",g.target_date||"—"]})};
  if(type==="Parcelas") return {title:"Parcelas e compromissos",headers:["Descrição","Categoria","Parcela","Total de parcelas","Valor","Data"],rows:expense.filter(x=>n(x.installments)>1).map(x=>[x.description||"Compra parcelada",categoryName(x.category),String(x.installment_number||1),String(x.installments),money(x.amount),dateBR(x.transaction_date)])};
  if(type==="Despesas fixas") return {title:"Despesas fixas",headers:["Conta","Categoria","Valor","Vencimento","Recorrente","Status"],rows:state.bills.filter(b=>b.recurring).map(b=>[b.name,categoryName(b.category),money(b.amount),String(b.due_day),"Sim",b.status||"Pendente"])};
  if(type==="Evolução patrimonial") {const contas=state.accounts.reduce((a,x)=>a+n(x.balance),0),guardado=state.goals.reduce((a,x)=>a+n(x.saved_amount),0),cartoes=state.cards.reduce((a,x)=>a+n(x.current_bill),0);return {title:"Evolução patrimonial",headers:["Componente","Valor"],rows:[["Saldo em contas",money(contas)],["Valores guardados em metas",money(guardado)],["Dívidas/faturas de cartões",money(cartoes)],["Patrimônio líquido estimado",money(contas+guardado-cartoes)]]};}
  return {title:"Relatório financeiro",headers:["Data","Tipo","Descrição","Categoria","Pagamento","Valor"],rows:tx.map(x=>[dateBR(x.transaction_date),txTypeLabel(x.type),x.description||"",categoryName(x.category),x.payment_method||"",money(x.amount)])};
}
function periodTx(period){const now=new Date();if(period==="current-month")return monthTx();if(period==="previous-month"){const y=now.getMonth()===0?now.getFullYear()-1:now.getFullYear(),m=now.getMonth()===0?11:now.getMonth()-1,pad=String(m+1).padStart(2,"0"),prefix=`${y}-${pad}`;return state.transactions.filter(x=>String(x.transaction_date).startsWith(prefix));}if(period==="year"){return state.transactions.filter(x=>String(x.transaction_date).startsWith(String(now.getFullYear())))}return state.transactions}
function reportTable(report){return`<div class="report-table-wrap"><table class="report-table"><thead><tr>${report.headers.map(h=>`<th>${esc(h)}</th>`).join("")}</tr></thead><tbody>${report.rows.length?report.rows.map(r=>`<tr>${r.map(c=>`<td>${esc(String(c))}</td>`).join("")}</tr>`).join(""):`<tr><td colspan="${report.headers.length}">Nenhum dado encontrado para este relatório.</td></tr>`}</tbody></table></div>`}
function reportsAnalysis(){return`<section class="card">${pageHeader("Relatórios","Escolha o tipo e o período para gerar um relatório organizado em Excel ou PDF.")}<div class="report-controls"><label>Tipo de relatório<select id="reportType">${["Resumo mensal","Gastos por categoria","Receitas x despesas","Contas e vencimentos","Cartões","Metas","Parcelas","Despesas fixas","Evolução patrimonial"].map(x=>`<option>${x}</option>`).join("")}</select></label><label>Período<select id="reportPeriod"><option value="current-month">Mês atual</option><option value="previous-month">Mês anterior</option><option value="year">Ano atual</option><option value="all">Todos os lançamentos</option></select></label><div class="report-actions"><button class="primary" id="generateReport">Gerar relatório</button><button class="secondary" id="exportExcel">Exportar Excel</button><button class="secondary" id="exportPdf">Gerar PDF</button></div></div><div id="reportPreview"></div></section>`}
function renderReportPreview(){const type=$("#reportType")?.value||"Resumo mensal",period=$("#reportPeriod")?.value||"current-month",r=reportRows(type,period);if($("#reportPreview"))$("#reportPreview").innerHTML=`<div class="report-preview"><div class="report-preview-head"><div><span class="eyebrow">Pré-visualização</span><h2>${esc(r.title)}</h2><p>${esc(periodLabel(period))}</p></div><span class="report-count">${r.rows.length} linha(s)</span></div>${reportTable(r)}</div>`}
function periodLabel(p){return({"current-month":"Mês atual","previous-month":"Mês anterior","year":"Ano atual",all:"Todos os lançamentos"}[p]||p)}
function reportWorkbookHtml(report){return`<html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;padding:24px;color:#24301f}h1{color:#566b2f}table{border-collapse:collapse;width:100%}th{background:#566b2f;color:#fff;text-align:left}th,td{border:1px solid #ccd5c6;padding:8px}tr:nth-child(even){background:#f3f6f0}</style></head><body><h1>Makaria — ${esc(report.title)}</h1><p>Gerado em ${new Date().toLocaleString("pt-BR")}</p>${reportTable(report)}</body></html>`}
function exportExcelReport(){const type=$("#reportType")?.value||"Resumo mensal",period=$("#reportPeriod")?.value||"current-month";const r=reportRows(type,period);downloadFile(reportWorkbookHtml(r),`makaria-${slug(type)}-${period}.xls`,"application/vnd.ms-excel;charset=utf-8");toast("Relatório Excel gerado.")}
function exportPdfReport(){const type=$("#reportType")?.value||"Resumo mensal",period=$("#reportPeriod")?.value||"current-month";const r=reportRows(type,period);const w=window.open("","_blank");if(!w){toast("O navegador bloqueou a janela do PDF.",true);return}w.document.write(`<html><head><title>Makaria — ${esc(r.title)}</title><style>body{font-family:Arial,sans-serif;padding:28px;color:#24301f}h1{color:#566b2f}p{color:#65705e}table{border-collapse:collapse;width:100%;font-size:12px}th{background:#566b2f;color:#fff}th,td{border:1px solid #ccd5c6;padding:7px;text-align:left}tr:nth-child(even){background:#f3f6f0}</style></head><body><h1>Makaria — ${esc(r.title)}</h1><p>${esc(periodLabel(period))} · Gerado em ${new Date().toLocaleString("pt-BR")}</p>${reportTable(r)}</body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),250)}
function slug(v){return String(v).normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")}


function profileSettings(){shell("Configurações","Perfil, salário, preferências e segurança.",settingsSection()+salarySection()+notificationsSection()+securitySection()+backupSection(),"Configurações")}
function moreOverview(){return`<div class="grid-3"><div class="feature-card"><b>Desafios e conquistas</b><span>Constância financeira sem incentivar consumo.</span></div><div class="feature-card"><b>Relatórios</b><span>Exporte análises organizadas em Excel ou PDF por período.</span></div><div class="feature-card"><b>Backup e segurança</b><span>Exporte seus dados e controle suas preferências.</span></div></div>`}
function topCategory(){const o={};monthTx().filter(x=>x.type==="expense").forEach(x=>o[categoryName(x.category)]=(o[categoryName(x.category)]||0)+n(x.amount));return Object.entries(o).sort((a,b)=>b[1]-a[1])[0]?.[0]}
function challengesSection(){const t=totals();return`<div class="challenge-grid">${[["3 dias sem gastos não essenciais","3 dias","Comece hoje"],["Uma semana dentro do limite","7 dias","Acompanhe o orçamento"],["Guardar R$ 5 por dia","R$ 5/dia","Crie uma meta"],["Registrar todos os gastos","7 dias","Não deixe nenhum lançamento de fora"]].map((c,i)=>`<article class="card challenge"><span>🏆</span><h2>${c[0]}</h2><p>${c[1]}</p><small>${c[2]}</small><div class="progress"><i style="width:${i===3?Math.min(100,state.transactions.length/7*100):0}%"></i></div></article>`).join("")}</div>`}
function achievementsSection(){const t=totals();const items=[["Primeira semana organizada",state.transactions.length>=7],["Primeiro mês dentro do orçamento",t.income>=t.expense&&t.income>0],["Primeira meta criada",state.goals.length>0],["Primeiros R$ 1.000 guardados",state.goals.reduce((a,g)=>a+n(g.saved_amount),0)>=1000],["Mês sem saldo negativo",t.balance>=0]];return`<section class="card timeline">${items.map(([x,ok])=>`<div class="timeline-item ${ok?"done":""}"><span>${ok?"✓":"○"}</span><div><b>${x}</b><small>${ok?"Conquista desbloqueada":"Ainda não desbloqueada"}</small></div></div>`).join("")}</section>`}
function categoriesSection(){return`<section class="card">${pageHeader("Gerenciamento de Categorias","Crie, edite e defina limites.")}<form id="categoryForm" class="form-grid"><label>Nome<input name="name" required placeholder="Ex.: Alimentação"></label><label>Ícone<input name="icon" maxlength="4" value="◈"></label><label>Limite Mensal<input name="monthly_limit" type="number" step="0.01" value="0"></label><div class="wide actions"><button class="primary">Criar Categoria</button></div></form></section><section class="category-grid">${state.categories.map(c=>`<article class="card"><span class="category-icon">${esc(c.icon||"◈")}</span><h2>${esc(c.name)}</h2><p class="muted">Limite: ${n(c.monthly_limit)?money(c.monthly_limit):"Não definido"}</p></article>`).join("")}</section>`}
function templatesSection(){const models=localGet("templates",[{name:"Almoço",category:"Alimentação",payment:"Débito",value:25},{name:"Transporte",category:"Transporte",payment:"Pix",value:15}]);return`<section class="card">${pageHeader("Modelos de Lançamento","Atalhos para despesas frequentes.",`<button class="secondary" id="addTemplate">+ Novo modelo</button>`)}${models.map((m,i)=>`<div class="dynamic-row"><div><b>${esc(m.name)}</b><small>${esc(m.category)} · ${esc(m.payment)} · valor sugerido ${money(m.value)}</small></div><button class="secondary" data-template-use="${i}">Usar</button></div>`).join("")}</section>`}
function notificationsSection(){const p=localGet("notifications",{due:true,bill:true,budget:true,negative:true,weekly:true,monthly:true});return`<section class="card">${pageHeader("Notificações","Escolha quais alertas o Makaria deve mostrar.")}<div class="check-list">${[["due","Conta próxima do vencimento"],["bill","Fatura próxima"],["budget","Categoria próxima do limite"],["negative","Risco de saldo negativo"],["weekly","Revisão semanal"],["monthly","Fechamento mensal"]].map(([k,l])=>`<label class="check-row"><span>${l}</span><input type="checkbox" data-notif="${k}" ${p[k]?"checked":""}></label>`).join("")}</div></section>`}
function backupSection(){return`<section class="card">${pageHeader("Exportação e Backup","Proteja seus lançamentos manuais.")}<div class="backup-actions"><button class="primary" id="exportJson">Baixar Backup JSON</button><button class="secondary" id="exportCsv2">Exportar Lançamentos CSV</button><label class="file-btn">Importar JSON<input id="importJson" type="file" accept="application/json"></label></div><div class="notice">O backup inclui dados disponíveis para o usuário atual e preferências locais. Antes de importar, mantenha uma cópia do backup atual.</div></section>`}
function securitySection(){return`<section class="card"><h2>Segurança</h2><div class="security-grid"><div><b>Ocultar valores</b><p class="muted">Ative no botão do cabeçalho para esconder valores.</p></div><div><b>Bloqueio automático</b><p class="muted">Controle de sessão e logout estão protegidos pelo Appwrite.</p></div><div><b>Isolamento por usuário</b><p class="muted">As consultas usam o ID do usuário autenticado e permissões de linha.</p></div></div></section>`}
function settingsSection(){const p=settingsPref();return`<section class="card">${pageHeader("Preferências","Personalize a experiência financeira.")}<div class="form-grid"><label>Dia do salário<input id="prefSalaryDay" type="number" min="1" max="31" value="${p.salaryDay}"></label><label>Início do mês financeiro<input id="prefMonthDay" type="number" min="1" max="31" value="${p.financialDay}"></label><label>Moeda<select id="prefCurrency"><option selected>BRL</option></select></label><label>Conta principal<select id="prefAccount">${formOptions(state.accounts)} </select></label><label class="wide">Nome exibido<input id="prefName" value="${esc(user?.name||"")}"></label></div><div class="actions"><button class="primary" id="savePrefs">Salvar preferências</button></div></section><section class="card"><h2>Conta</h2><p>E-mail: <b>${esc(user?.email||"")}</b></p><button class="danger-btn" id="logout2">Sair da conta</button></section>`}
function salarySection(){const base=n(state.settings?.gross_salary),items=localGet("salaryitems",{income:[],deduction:[]}),cycle=nextSalaryReceipt(),p=settingsPref(),hasAdvance=p.hasAdvance!==false && n(state.settings?.advance_pct)>0;return`<section class="card">${pageHeader("Salário e Descontos","Configure sua renda e veja automaticamente como ela entra no planejamento mensal.")}<form id="salaryForm" class="form-grid"><label>Renda Bruta<input name="gross_salary" type="number" step="0.01" value="${base}"></label><label>Você recebe adiantamento salarial?<select name="has_advance" id="hasAdvance"><option value="true" ${hasAdvance?"selected":""}>Sim</option><option value="false" ${!hasAdvance?"selected":""}>Não</option></select></label><label id="advancePctBox" class="${hasAdvance?"":"hide"}">Percentual do Adiantamento (%)<input name="advance_pct" type="number" min="0" max="100" step="0.01" value="${n(state.settings?.advance_pct)}"><small class="field-help">Informe livremente o percentual recebido como adiantamento.</small></label><label id="advanceDayBox" class="${hasAdvance?"":"hide"}">Dia do Adiantamento<input name="advance_day" type="number" min="1" max="28" value="${Number(p.advanceDay)||20}"></label><label>Pagamento Principal<select name="salary_rule"><option selected>5º dia útil do mês seguinte</option></select></label><div class="wide salary-calc-preview"><b>Ciclo salarial configurado</b><p>Adiantamento: <strong>${money(cycle.advance)}</strong> em ${dateBR(cycle.advanceDate)}.</p><p>Recebimento principal: <strong>${money(cycle.final)}</strong> em ${dateBR(cycle.finalDate)}.</p><p>Total líquido estimado no ciclo: <strong>${money(cycle.total)}</strong>.</p><small>O adiantamento é parte do mesmo salário e não é contabilizado duas vezes como receita.</small></div><div class="wide actions"><button class="primary">Salvar Salário</button></div></form></section><div class="metrics">${metric("Renda Bruta",money(base),"Salário configurado","↗")}${metric("Adiantamento",money(cycle.advance),`${cycle.advancePct.toFixed(2)}%`,"20")}${metric("Recebimento Principal",money(cycle.final),"5º dia útil","5")}${metric("Total Líquido Estimado",money(cycle.total),"Após descontos configurados","✓")}</div><section class="card"><div class="card-head"><div><h2>Próximos Recebimentos</h2><p>Os recebimentos aparecem separadamente no planejamento, mas pertencem ao mesmo salário.</p></div></div><div class="timeline">${hasAdvance?`<div class="timeline-item"><span>${Number(p.advanceDay)||20}</span><div><b>Adiantamento salarial</b><small>${dateBR(cycle.advanceDate)} · ${money(cycle.advance)}</small></div></div>`:""}<div class="timeline-item"><span>5</span><div><b>Recebimento principal</b><small>${dateBR(cycle.finalDate)} · ${money(cycle.final)}</small></div></div></div></section><section class="grid-2"><div class="card">${pageHeader("Rendas Extras","Valor fixo ou percentual.",`<button class="secondary" data-salary-add="income">+ Adicionar</button>`)}${salaryRows(items.income,"income",base)}</div><div class="card">${pageHeader("Descontos","Valor fixo ou percentual da renda bruta.",`<button class="secondary" data-salary-add="deduction">+ Adicionar</button>`)}${salaryRows(items.deduction,"deduction",base)}</div></div>`}
function salaryRows(arr,type,base){return arr.length?arr.map((x,i)=>`<div class="dynamic-row"><div><b>${esc(cap(x.name))}</b><small>${x.mode==="percent"?`${n(x.value).toFixed(2)}% da renda bruta`:"Valor fixo"}</small></div><strong>${money(salaryValue(x,base))}</strong><button class="icon-delete" data-salary-del="${type}" data-salary-index="${i}">×</button></div>`).join(""):empty(type==="income"?"Nenhuma renda extra.":"Nenhum desconto cadastrado.")}
function salaryValue(x,base){return x.mode==="percent"?base*n(x.value)/100:n(x.value)}

function bindQuick(){$$('[data-quick]').forEach(b=>b.onclick=()=>{const q=b.dataset.quick;if(q==="buy"){state.page="planning";state.sub="simulations";render()}else openEntryModal(q)})}
function openEntryModal(type="expense"){$("#modal").classList.remove("hide");$("#modal").innerHTML=`<div class="modal card"><div class="modal-head"><div><span class="eyebrow">Lançamento rápido</span><h2>${type==="bill"?"Nova conta a pagar":type==="goal"?"Adicionar à meta":"Novo ${txTypeLabel(type)}"}</h2></div><button data-close>×</button></div>${type==="bill"?billModal():type==="goal"?goalDepositModal():txModal(type)}</div>`;$$('[data-close]').forEach(x=>x.onclick=closeModal);if(type==="bill")bindBillModal();else if(type==="goal")bindGoalDeposit();else bindTxModal(type)}
function txModal(type){return`<form id="quickTx" class="form-grid"><label>Valor<input name="amount" type="number" step="0.01" required autofocus></label><label>Categoria<select name="category">${formOptions(state.categories,"name","name","")}</select></label><label>Data<input name="transaction_date" type="date" value="${today()}"></label><label>Forma de pagamento<select name="payment_method"><option>Pix</option><option>Débito</option><option>Cartão de Crédito</option><option>Dinheiro</option><option>Boleto</option><option>Transferência</option></select></label><label class="wide">Descrição<input name="description" placeholder="Ex.: Almoço, salário, mercado"></label><details class="wide"><summary>Mais opções</summary><div class="form-grid inner"><label>Estabelecimento<input name="establishment"></label><label>Status<select name="status"><option>Pago</option><option>Pendente</option></select></label><label>Parcelas<input name="installments" type="number" min="1" value="1"></label><label>Etiquetas<input name="tags" placeholder="ex.: casa, urgente"></label><label class="wide">Observação<textarea name="note"></textarea></label></div></details><div class="wide actions"><button class="primary">Salvar lançamento</button></div></form>`}
function bindTxModal(type){$("#quickTx").onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.type=type;d.amount=n(d.amount);d.installments=Math.max(1,Number(d.installments)||1);d.installment_number=1;const meta={status:d.status||"Pago",establishment:d.establishment||"",note:d.note||"",tags:(d.tags||"").split(",").map(x=>x.trim()).filter(Boolean)};delete d.status;delete d.establishment;delete d.note;delete d.tags;try{const r=await createRow(C.tables.transactions,d);saveTxMeta(r.$id,meta);toast("Lançamento salvo.");closeModal();await load();render()}catch(err){toast(err.message,true)}}}
function billModal(){return`<form id="quickBill" class="form-grid"><label>Nome<input name="name" required placeholder="Internet, Faculdade..."></label><label>Valor<input name="amount" type="number" step="0.01" required></label><label>Vencimento<input name="due_day" type="number" min="1" max="31" required></label><label>Categoria<select name="category">${formOptions(state.categories)}</select></label><label>Status<select name="status"><option>Pendente</option><option>Pago</option></select></label><label>Recorrente<select name="recurring"><option value="true">Sim</option><option value="false">Não</option></select></label><div class="wide actions"><button class="primary">Salvar conta</button></div></form>`}
function bindBillModal(){$("#quickBill").onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.amount=n(d.amount);d.due_day=Number(d.due_day);d.recurring=d.recurring==="true";try{await createRow(C.tables.bills,d);toast("Conta cadastrada.");closeModal();await load();render()}catch(err){toast(err.message,true)}}}
function goalDepositModal(){return`<form id="goalDeposit" class="form-grid"><label>Meta<select name="goal">${state.goals.map(g=>`<option value="${g.$id}">${esc(g.name)}</option>`).join("")}</select></label><label>Valor<input name="value" type="number" step="0.01" required></label><div class="wide actions"><button class="primary">Registrar depósito</button></div></form>`}
function bindGoalDeposit(){$("#goalDeposit").onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget)),g=state.goals.find(x=>x.$id===d.goal);if(!g)return;try{await updateRow(C.tables.goals,g.$id,{saved_amount:n(g.saved_amount)+n(d.value)});toast("Depósito registrado.");closeModal();await load();render()}catch(err){toast(err.message,true)}}}
function modal(html){$("#modal").classList.remove("hide");$("#modal").innerHTML=`<div class="modal card">${html}</div>`;$("#modal").onclick=e=>{if(e.target.id==="modal")closeModal()};$$(`[data-close]`,$("#modal")).forEach(b=>b.onclick=closeModal)}
function closeModal(){$("#modal").classList.add("hide");$("#modal").innerHTML=""}
function bindForms(){const a=$("#accountForm");if(a)a.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(a));d.balance=n(d.balance);d.due_day=Number(d.due_day)||0;d.recurring=d.recurring==="true";try{await createRow(C.tables.accounts,d);toast("Conta adicionada.");await load();render()}catch(err){toast(err.message,true)}};const c=$("#cardForm");if(c)c.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(c));d.credit_limit=n(d.credit_limit);d.current_bill=0;d.closing_day=Number(d.closing_day)||0;d.due_day=Number(d.due_day)||0;try{await createRow(C.tables.cards,d);toast("Cartão adicionado.");await load();render()}catch(err){toast(err.message,true)}};const g=$("#goalForm");if(g)g.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(g));d.target_amount=n(d.target_amount);d.saved_amount=n(d.saved_amount);d.name=cap(d.name);try{await createRow(C.tables.goals,d);toast("Meta criada.");await load();render()}catch(err){toast(err.message,true)}};const cat=$("#categoryForm");if(cat)cat.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(cat));d.name=cap(d.name);d.monthly_limit=n(d.monthly_limit);try{await createRow(C.tables.categories,d);toast("Categoria criada.");await load();render()}catch(err){toast(err.message,true)}};const sal=$("#salaryForm");if(sal)sal.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(sal));d.gross_salary=n(d.gross_salary);d.advance_pct=d.has_advance==="true"?Math.max(0,Math.min(100,n(d.advance_pct))):0;const p=settingsPref();p.hasAdvance=d.has_advance==="true";p.advanceDay=Number(d.advance_day)||20;localSet("prefs",p);delete d.has_advance;delete d.advance_day;delete d.salary_rule;try{await updateRow(C.tables.settings,state.settings.$id,d);toast("Salário e adiantamento salvos.");await load();render()}catch(err){toast(err.message,true)}};const ha=$("#hasAdvance");if(ha)ha.onchange=()=>{$("#advancePctBox")?.classList.toggle("hide",ha.value!=="true");$("#advanceDayBox")?.classList.toggle("hide",ha.value!=="true")};$$('[data-pay-bill]').forEach(b=>b.onclick=()=>payBill(b.dataset.payBill));$$('[data-salary-add]').forEach(b=>openSalaryItem(b.dataset.salaryAdd));$$('[data-salary-del]').forEach(b=>{b.onclick=()=>{const items=localGet("salaryitems",{income:[],deduction:[]}),type=b.dataset.salaryDel,i=Number(b.dataset.salaryIndex);items[type].splice(i,1);localSet("salaryitems",items);render()}});const rf=$("#reconcileForm");if(rf)rf.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(rf)),a=state.accounts.find(x=>x.$id===d.account),real=n(d.real),calc=n(a?.balance),diff=real-calc;$("#reconcileResult").innerHTML=`<div class="reconcile"><b>Saldo calculado: ${money(calc)}</b><b>Saldo informado: ${money(real)}</b><strong>Diferença: ${money(diff)}</strong><p>${Math.abs(diff)>0.01?`Pode existir uma movimentação de ${money(Math.abs(diff))} que ainda não foi registrada.`:"Os saldos coincidem."}</p></div>`};const buy=$("#buyForm");if(buy)buy.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(buy)),price=n(d.price),i=Math.max(1,Number(d.installments)||1),interest=n(d.interest),total=price*(1+interest/100),parcel=total/i,t=totals(),free=Math.max(0,t.balance-state.bills.filter(b=>b.status!=="Pago").reduce((a,b)=>a+n(b.amount),0)),rating=price<=free?"Pode comprar":parcel<=free/Math.max(1,daysUntilSalary())*30?"Melhor esperar":"Não recomendado agora";$("#buyResult").innerHTML=`<div class="buy-result ${rating.replaceAll(" ","-").toLowerCase()}"><span>${rating}</span><h3>${money(parcel)} × ${i}</h3><p>Total com juros: ${money(total)} · ${t.income?((parcel/t.income)*100).toFixed(1):0}% da renda mensal.</p><small>Esta simulação não altera seus dados reais.</small></div>`};$$('[data-scenario]').forEach(b=>b.onclick=()=>{const t=totals(),factor=b.dataset.scenario==="conservative"?1.25:b.dataset.scenario==="optimistic"?.8:1,project=t.balance-t.expense*factor+Math.max(0,t.income-t.expense);$("#scenarioResult").innerHTML=`<b>${b.textContent}</b><p>Saldo projetado: <strong>${money(project)}</strong></p><small>Projeção educativa usando o comportamento atual e um fator de despesas de ${factor.toFixed(2)}.</small>`});const genReport=$("#generateReport");if(genReport)genReport.onclick=renderReportPreview;const reportType=$("#reportType"),reportPeriod=$("#reportPeriod");if(reportType)reportType.onchange=renderReportPreview;if(reportPeriod)reportPeriod.onchange=renderReportPreview;const exExcel=$("#exportExcel"),exPdf=$("#exportPdf");if(exExcel)exExcel.onclick=exportExcelReport;if(exPdf)exPdf.onclick=exportPdfReport;if(reportType)renderReportPreview();const ex=$("#exportCsv"),ex2=$("#exportCsv2");if(ex)ex.onclick=exportCsv;if(ex2)ex2.onclick=exportCsv;const ej=$("#exportJson");if(ej)ej.onclick=exportJson;const imp=$("#importJson");if(imp)imp.onchange=importJson;const ask=$("#askAssistant");if(ask)ask.onclick=askAssistant;$$('[data-q]').forEach(b=>b.onclick=()=>{$("#assistantQ").value=b.dataset.q;askAssistant()});const saveP=$("#savePrefs");if(saveP)saveP.onclick=()=>{const p=settingsPref();p.salaryDay=Number($("#prefSalaryDay").value)||5;p.financialDay=Number($("#prefMonthDay").value)||1;p.mainAccount=$("#prefAccount").value||"";localSet("prefs",p);toast("Preferências salvas.")};const lo=$("#logout2");if(lo)lo.onclick=logout;$$('[data-notif]').forEach(x=>x.onchange=()=>{const p=localGet("notifications",{});p[x.dataset.notif]=x.checked;localSet("notifications",p)});const addT=$("#addTemplate");if(addT)addT.onclick=()=>{const models=localGet("templates",[]);const name=prompt("Nome do modelo");if(!name)return;const value=Number(prompt("Valor sugerido",25))||0;models.push({name,category:"Alimentação",payment:"Pix",value});localSet("templates",models);render()};$$('[data-template-use]').forEach(b=>b.onclick=()=>{const m=localGet("templates",[])[Number(b.dataset.templateUse)];openEntryModal("expense");setTimeout(()=>{if(m){$("#quickTx [name=amount]").value=m.value;$("#quickTx [name=category]").value=m.category;$("#quickTx [name=payment_method]").value=m.payment}},0)});const csv=$("#exportCsv");if(csv)csv.onclick=exportCsv}
async function payBill(id){const b=state.bills.find(x=>x.$id===id);if(!b)return;try{await updateRow(C.tables.bills,id,{status:"Pago"});toast("Conta marcada como paga.");await load();render()}catch(e){toast(e.message,true)}}
function openSalaryItem(type){const base=n(state.settings?.gross_salary);modal(`<div class="modal card"><div class="modal-head"><h2>${type==="income"?"Adicionar Renda Extra":"Adicionar Desconto"}</h2><button data-close>×</button></div><form id="salaryItemForm" class="form-grid"><label class="wide">Nome<input name="name" required></label><label>Forma de cálculo<select name="mode"><option value="fixed">Valor Fixo (R$)</option><option value="percent">Percentual da Renda Bruta (%)</option></select></label><label>Valor<input name="value" type="number" step="0.01" required></label><div class="wide actions"><button class="primary">Adicionar</button></div></form></div>`);$("#salaryItemForm").onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget)),items=localGet("salaryitems",{income:[],deduction:[]});items[type].push({name:d.name,mode:d.mode,value:n(d.value)});localSet("salaryitems",items);closeModal();render()}}
function exportCsv(){const lines=[["Data","Tipo","Descrição","Categoria","Pagamento","Valor"],...state.transactions.map(x=>[x.transaction_date,txTypeLabel(x.type),x.description||"",categoryName(x.category),x.payment_method||"",n(x.amount).toFixed(2)])];downloadFile(lines.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(",")).join("\n"),"makaria-lancamentos.csv","text/csv;charset=utf-8")}
function exportJson(){downloadFile(JSON.stringify({transactions:state.transactions,goals:state.goals,accounts:state.accounts,categories:state.categories,bills:state.bills,cards:state.cards,settings:state.settings,local:{prefs:settingsPref(),txmeta:localGet("txmeta",{}),templates:localGet("templates",[]),salaryitems:localGet("salaryitems",{})}},null,2),"makaria-backup.json","application/json")}
function downloadFile(content,name,type){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
async function importJson(e){const f=e.target.files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!confirm("Importar este backup como novos registros?"))return;for(const x of data.transactions||[]){const d={type:x.type,amount:n(x.amount),category:x.category,description:x.description||"",transaction_date:x.transaction_date,payment_method:x.payment_method||"Pix",installments:x.installments||1,installment_number:x.installment_number||1};const r=await createRow(C.tables.transactions,d);if(data.local?.txmeta?.[x.$id])saveTxMeta(r.$id,data.local.txmeta[x.$id])}toast("Backup importado. Itens principais adicionados.");await load();render()}catch(err){toast("Backup inválido: "+err.message,true)}}
function bindGlobal(){const theme=$("#theme");if(theme)theme.onclick=()=>{document.body.classList.toggle("dark");localStorage.setItem("makaria_theme",document.body.classList.contains("dark")?"dark":"light")};const hide=$("#hideValues");if(hide)hide.onclick=()=>{const p=settingsPref();p.hideValues=!p.hideValues;localSet("prefs",p);document.body.classList.toggle("hide-values",p.hideValues)};const logoutBtn=$("#logout");if(logoutBtn)logoutBtn.onclick=logout;const profile=$("#profileBtn");if(profile)profile.onclick=()=>{state.page="profile";state.sub="settings";render()}}
async function logout(){try{await account.deleteSession("current")}catch{}location.reload()}
function render(){nav();const pages={home,transactions,planning,analysis,profile:profileSettings};(pages[state.page]||home)();bindForms();bindGlobal();$$(`[data-sub]`).forEach(b=>b.onclick=()=>{state.sub=b.dataset.sub;render()});$$(`.bottom-nav [data-page]`).forEach(b=>b.onclick=()=>{state.page=b.dataset.page;state.sub=state.page==="planning"?"budget":state.page==="analysis"?"overview":"overview";render()});const plus=$("#centralPlus");if(plus)plus.onclick=()=>openEntryModal("expense");document.body.classList.toggle("hide-values",settingsPref().hideValues)}
function auth(){
  $$(".tabs button").forEach(btn=>btn.onclick=()=>{$$(".tabs button").forEach(x=>x.classList.remove("active"));btn.classList.add("active");const sign=btn.dataset.mode==="signup";$("#nameBox").classList.toggle("hide",!sign);$("#authBtn").textContent=sign?"Criar Conta":"Entrar";$("#authForm").dataset.mode=btn.dataset.mode});$("#authForm").dataset.mode="login";
  $("#authForm").onsubmit=async e=>{e.preventDefault();const sign=e.currentTarget.dataset.mode==="signup",email=$("#email").value.trim(),pass=$("#pass").value,name=$("#name").value.trim();$("#authBtn").disabled=true;$("#authMsg").textContent="";try{if(sign){if(!name)throw new Error("Informe seu nome.");await account.create(ID.unique(),email,pass,name);await account.createEmailPasswordSession(email,pass)}else await account.createEmailPasswordSession(email,pass);location.reload()}catch(err){$("#authMsg").textContent=err.message||"Não foi possível concluir a operação."}finally{$("#authBtn").disabled=false}}}
async function start(){auth();try{user=await account.get();$("#auth").classList.add("hide");$("#app").classList.remove("hide");$("#hello").textContent=`Olá, ${user.name||"Usuário"}`;render();try{await ensureProfile();await load();render()}catch(err){console.error("Falha ao carregar dados do Appwrite:",err);toast("Não foi possível carregar os dados salvos. O aplicativo continuará disponível com os dados locais.",true);render()}}catch(err){if(err?.code===401){$("#auth").classList.remove("hide");$("#app").classList.add("hide")}else{console.error(err);toast(err?.message||"Não foi possível iniciar o Makaria.",true)}}}
start();
